    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]

    def spans(n, lines):
        out, start = [], 0
        for x in lines:
            if start < x:
                out.append((start, x))
            start = x + 1
        if start < n:
            out.append((start, n))
        return out

